    buy_book = []   # (price, arrival_time, id, qty) - sorted by price descending, then arrival ascending
    sell_book = []  # (price, arrival_time, id, qty) - sorted by price ascending, then arrival ascending
    cancelled = set()
    arrival_time = 0

    for order in orders:
        arrival_time += 1
        order_type = order[0]

        if order_type == 'cancel':
            order_id = order[1]
            cancelled.add(order_id)
            continue

        order_id = order[1]
        side = order[2]

        if order_type == 'limit':
            price = order[3]
            qty = order[4]

            remaining = qty
            if side == 'buy':
                # Match against resting sells (lowest price first, then earliest arrival)
                while remaining > 0 and sell_book:
                    if sell_book[0][0] <= price:
                        sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]
                        trade_qty = min(remaining, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining -= trade_qty
                        if sell_qty == trade_qty:
                            sell_book.pop(0)
                        else:
                            sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)
                    else:
                        break

                # Rest remaining
                if remaining > 0:
                    buy_book.append((price, arrival_time, order_id, remaining))
                    # Keep sorted by price descending, then arrival ascending
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
            else:  # sell
                # Match against resting buys (highest price first, then earliest arrival)
